package com.wiseway.web;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { record ErrorResponse(Instant timestamp,int status,String code,String message,Map<String,String> fieldErrors,String path){} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){var fields=new LinkedHashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(x->fields.putIfAbsent(x.getField(),x.getDefaultMessage()));return response(HttpStatus.BAD_REQUEST,"VALIDATION_ERROR","Request validation failed",fields,r);} @ExceptionHandler({IllegalArgumentException.class}) ResponseEntity<ErrorResponse> bad(Exception e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,"BAD_REQUEST",e.getMessage(),Map.of(),r);} @ExceptionHandler(NotFoundException.class) ResponseEntity<ErrorResponse> notFound(Exception e,HttpServletRequest r){return response(HttpStatus.NOT_FOUND,"NOT_FOUND",e.getMessage(),Map.of(),r);} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> internal(Exception e,HttpServletRequest r){return response(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","Something went wrong. Please try again.",Map.of(),r);} private ResponseEntity<ErrorResponse> response(HttpStatus s,String c,String m,Map<String,String> f,HttpServletRequest r){return ResponseEntity.status(s).body(new ErrorResponse(Instant.now(),s.value(),c,m,f,r.getRequestURI()));}}
